        ("bias", "/ˈbaɪ.əs/", "noun", "B2", "Thiên kiến nhận thức (Cognitive Bias)", "Prejudice in favor of or against one thing, person, or group.", ["Confirmation bias leads people to seek only facts that confirm their beliefs."], ["prejudice", "cognitive error"], ["cognitive bias", "confirmation bias"]),
