        ("venomous", "/ˈven.ə.məs/", "adjective", "B1", "Có nọc độc nguy hiểm khi cắn/chích", "Capable of injecting venom by means of a bite or sting.", ["The inland taipan is the world's most venomous land snake."], ["poisonous", "toxic"], ["venomous snake", "venomous spider"]),
